async function getTimes(url) {
  try {
    const res = await fetch(url);
    const html = await res.text();
    const prepMatch = html.match(/prepTime["\s:]+(PT[^"]+)/i);
    const cookMatch = html.match(/cookTime["\s:]+(PT[^"]+)/i);
    const totalMatch = html.match(/totalTime["\s:]+(PT[^"]+)/i);
    const titleMatch = html.match(/<title>([^<]+)<\/title>/i);
    return {
      url,
      title: titleMatch ? titleMatch[1].trim() : 'unknown',
      prep: prepMatch ? prepMatch[1] : null,
      cook: cookMatch ? cookMatch[1] : null,
      total: totalMatch ? totalMatch[1] : null,
    };
  } catch (e) {
    return { url, error: e.message };
  }
}

return Promise.all(urls.map(getTimes));

