function extractRatings() {
  const results = [];
  // Find all star rating components
  const starContainers = document.querySelectorAll('[id^="mntl-recipe-star-rating"]');
  starContainers.forEach((container, idx) => {
    const card = container.closest('a');
    const titleEl = card ? card.querySelector('span span') : null;
    const title = titleEl ? titleEl.textContent.trim() : 'unknown';

    // Get all SVG paths in this rating container with their fill
    const svgs = container.querySelectorAll('svg');
    let starInfo = [];
    svgs.forEach((svg, svgIdx) => {
      // Get the viewBox and width
      const viewBox = svg.getAttribute('viewBox') || '';
      const width = svg.getAttribute('width') || '';

      // Find elements with specific star portions
      const allElements = svg.querySelectorAll('*');
      allElements.forEach(el => {
        const tagName = el.tagName;
        const fill = el.getAttribute('fill') || '';
        const style = el.getAttribute('style') || '';
        const transform = el.getAttribute('transform') || '';
        const x = el.getAttribute('x') || '';
        const widthAttr = el.getAttribute('width') || '';
        if (tagName === 'use') {
          starInfo.push({svgIdx, tag: 'use', href: el.getAttribute('href') || el.getAttribute('xlink:href') || '', transform});
        }
        if (tagName === 'rect' || tagName === 'path') {
          starInfo.push({svgIdx, tag: tagName, fill, transform, x, widthAttr, d: el.getAttribute('d')?.slice(0,30) || ''});
        }
      });
    });

    // Also try to find rating in aria-label
    const ratingValue = container.getAttribute('aria-label') || '';
    const ratingNumberEl = container.parentElement ? container.parentElement.querySelector('.mntl-recipe-card-meta__rating') : null;
    const altRating = ratingNumberEl ? ratingNumberEl.textContent : '';

    results.push({idx, title, ratingAriaLabel: ratingValue, altRating: altRating, starInfo: starInfo.slice(0, 30)});
  });
  return results;
}

return extractRatings();

